import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class SynchronizedConcurrentMapBefore {
    private ConcurrentMap<String, String> cache = new ConcurrentHashMap<>();

    public void updateCache(String key, String value) {
        // Redundant synchronization removed
        System.out.println("Updating cache for key: " + key);
        cache.put(key, value);
    }

    public boolean checkAndAdd(String key, String value) {
        boolean added;
        // Another match, synchronized block removed
        added = cache.putIfAbsent(key, value) == null;
        return added;
    }

    public void doNothing() {
        // Empty block also matches
    }
}

