public class NegativeExample {
    public void processString(String text) {
        // Should not match if source version is < Java 11
        // (handled by sourceVersionGE(11) guard)
        if (text != null && !text.trim().isEmpty()) {
            System.out.println("Should not match if Java < 11.");
        }

        // Should not match a simple isEmpty() call
        if (!text.isEmpty()) {
            System.out.println("Only checks length, not content after trim.");
        }

        // Should not match if trim() is not present
        if (!text.equals(" ")) {
            System.out.println("Not just a space.");
        }
    }
}

